const event = $json.body ?? $json;
const document = event.data;
if (!event.event_id || !event.event || !document) throw new Error('Invalid PandaDoc event payload');
if (event.event !== 'document_state_changed') throw new Error(`Unsupported PandaDoc event: ${event.event}`);
const onboardingId = document.metadata?.onboarding_id ?? '';
const sourceDealId = document.metadata?.source_deal_id ?? '';
if (!onboardingId && !sourceDealId) throw new Error('PandaDoc metadata requires onboarding_id or source_deal_id');
const completed = ['document.completed', 'completed'].includes(document.status);
const rejected = ['document.declined', 'declined'].includes(document.status);
if (!completed && !rejected) throw new Error(`Unsupported PandaDoc status: ${document.status}`);
const normalized = {
  provider: 'pandadoc', event_id: String(event.event_id), event_type: String(event.event),
  onboarding_id: String(onboardingId), source_deal_id: String(sourceDealId),
  requirement_key: 'contract', result: completed ? 'signed' : 'rejected',
  external_object_id: String(document.id ?? '')
};
return [{ json: { ...normalized, payload_base64: Buffer.from(JSON.stringify(normalized)).toString('base64') } }];
